#[cfg(test)]
mod ast_matcher_tests {
    use super::*;

    const REPEATED_VALUE: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Ident,
        label: Some(0),
    };
    const REPEATED_VALUES: AstPattern = AstPattern::Rep(&REPEATED_VALUE);
    const TRAILING_VALUE: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Eof,
        label: Some(1),
    };
    const REPEATED_THEN_TRAILING_PARTS: [AstPattern; 2] = [REPEATED_VALUES, TRAILING_VALUE];
    const REPEATED_THEN_TRAILING: AstPattern =
        AstPattern::Seq(&REPEATED_THEN_TRAILING_PARTS);

    const LEFT_VALUE: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Ident,
        label: Some(0),
    };
    const RIGHT_VALUE: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Ident,
        label: Some(1),
    };
    const OVERLAPPING_BRANCHES: [AstPattern; 2] = [LEFT_VALUE, RIGHT_VALUE];
    const OVERLAPPING_LABELS: AstPattern = AstPattern::Alt(&OVERLAPPING_BRANCHES);

    const RECOVERED_LONG_PREFIX: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Ident,
        label: None,
    };
    const RECOVERED_COMMA: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Comma,
        label: Some(0),
    };
    const RECOVERED_LONG_PARTS: [AstPattern; 2] = [RECOVERED_LONG_PREFIX, RECOVERED_COMMA];
    const RECOVERED_LONG: AstPattern = AstPattern::Seq(&RECOVERED_LONG_PARTS);
    const RECOVERED_BRANCHES: [AstPattern; 2] = [RECOVERED_LONG, RECOVERED_COMMA];
    const RECOVERED_ALTERNATIVE: AstPattern = AstPattern::Alt(&RECOVERED_BRANCHES);
    const RECOVERED_REPETITION: AstPattern = AstPattern::Rep(&RECOVERED_ALTERNATIVE);

    const NESTED_VALUE: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Ident,
        label: None,
    };
    const NESTED_VALUES: AstPattern = AstPattern::Rep(&NESTED_VALUE);
    const NESTED_END: AstPattern = AstPattern::Atom {
        kind: SyntaxKind::Comma,
        label: Some(0),
    };
    const NESTED_ITERATION_PARTS: [AstPattern; 2] = [NESTED_VALUES, NESTED_END];
    const NESTED_ITERATION: AstPattern = AstPattern::Seq(&NESTED_ITERATION_PARTS);
    const NESTED_REPETITION: AstPattern = AstPattern::Rep(&NESTED_ITERATION);

    fn synthetic_node(values: usize, eof: bool) -> SyntaxNode {
        let mut builder = rowan::GreenNodeBuilder::new();
        builder.start_node(rowan::SyntaxKind(SyntaxKind::Source as u16));
        for _ in 0..values {
            builder.token(rowan::SyntaxKind(SyntaxKind::Ident as u16), "value");
        }
        if eof {
            builder.token(rowan::SyntaxKind(SyntaxKind::Eof as u16), "");
        }
        builder.finish_node();
        SyntaxNode::new_root(builder.finish())
    }

    fn synthetic_kinds(kinds: &[SyntaxKind]) -> SyntaxNode {
        let mut builder = rowan::GreenNodeBuilder::new();
        builder.start_node(rowan::SyntaxKind(SyntaxKind::Source as u16));
        for kind in kinds {
            match kind {
                SyntaxKind::Missing => {
                    builder.start_node(rowan::SyntaxKind(SyntaxKind::Missing as u16));
                    builder.finish_node();
                }
                SyntaxKind::Ident => {
                    builder.token(rowan::SyntaxKind(SyntaxKind::Ident as u16), "value");
                }
                SyntaxKind::Comma => {
                    builder.token(rowan::SyntaxKind(SyntaxKind::Comma as u16), ",");
                }
                _ => panic!("unsupported synthetic kind: {kind:?}"),
            }
        }
        builder.finish_node();
        SyntaxNode::new_root(builder.finish())
    }

    #[test]
    fn repetition_uses_linear_frontier_work_and_persistent_captures() {
        let mut previous_work = None;
        for count in [100, 200, 400, 800, 1_600] {
            let node = synthetic_node(count, true);
            let (repeated, repeated_work) =
                ast_fields_with_work(&node, &REPEATED_THEN_TRAILING, 0);
            let (trailing, trailing_work) =
                ast_fields_with_work(&node, &REPEATED_THEN_TRAILING, 1);

            assert_eq!(repeated.len(), count);
            assert!(repeated.iter().all(Option::is_some));
            assert_eq!(trailing.len(), 1);
            assert!(trailing[0].is_some());
            assert_eq!(repeated_work, 3 * count + 3);
            assert_eq!(trailing_work, 3 * count + 3);
            if let Some(previous) = previous_work {
                assert!(repeated_work <= 2 * previous + 8);
            }
            previous_work = Some(repeated_work);
        }
    }

    #[test]
    fn overlapping_alternatives_prefer_the_selected_label_capture() {
        let node = synthetic_node(1, false);
        let left = ast_fields(&node, &OVERLAPPING_LABELS, 0);
        let right = ast_fields(&node, &OVERLAPPING_LABELS, 1);

        assert_eq!(left.len(), 1);
        assert_eq!(left[0].as_ref().unwrap().kind(), SyntaxKind::Ident);
        assert_eq!(right.len(), 1);
        assert_eq!(right[0].as_ref().unwrap().kind(), SyntaxKind::Ident);
    }

    #[test]
    fn missing_prefix_improves_an_endpoint_before_it_is_expanded() {
        let recovered = synthetic_kinds(&[
            SyntaxKind::Missing,
            SyntaxKind::Comma,
            SyntaxKind::Comma,
        ]);
        let fields = ast_fields(&recovered, &RECOVERED_REPETITION, 0);
        assert_eq!(fields.len(), 3);
        assert!(fields[0].is_none());
        assert_eq!(fields.into_iter().flatten().count(), 2);

        let long_then_short = synthetic_kinds(&[
            SyntaxKind::Ident,
            SyntaxKind::Comma,
            SyntaxKind::Comma,
        ]);
        let fields = ast_fields(&long_then_short, &RECOVERED_REPETITION, 0);
        assert_eq!(fields.len(), 2);
        assert!(fields.iter().all(Option::is_some));

        let three_short = synthetic_kinds(&[
            SyntaxKind::Comma,
            SyntaxKind::Comma,
            SyntaxKind::Comma,
        ]);
        let fields = ast_fields(&three_short, &RECOVERED_REPETITION, 0);
        assert_eq!(fields.len(), 3);
        assert!(fields.iter().all(Option::is_some));
    }

    #[test]
    fn nested_repetition_uses_bounded_automaton_work() {
        let mut previous_work = None;
        for count in [50, 100, 200, 400] {
            let node = synthetic_kinds(&vec![SyntaxKind::Missing; count]);
            let (fields, work) = ast_fields_with_work(&node, &NESTED_REPETITION, 0);

            assert_eq!(fields.len(), count);
            assert!(fields.iter().all(Option::is_none));
            assert_eq!(work, 11 * count + 6);
            if let Some(previous) = previous_work {
                assert!(work <= 2 * previous + 6);
            }
            previous_work = Some(work);
        }
    }
}

