#[derive(Clone, Debug, Eq, Hash, PartialEq)]
pub struct Source { syntax: SyntaxNode }

impl AstNode for Source {
    type Language = AllenLanguage;

    fn can_cast(kind: SyntaxKind) -> bool { kind == SyntaxKind::Source }

    fn cast(syntax: SyntaxNode) -> Option<Self> { Self::can_cast(syntax.kind()).then_some(Self { syntax }) }

    fn syntax(&self) -> &SyntaxNode { &self.syntax }
}

impl Source {
    #[must_use]
    pub fn children(&self) -> impl Iterator<Item = SyntaxNode> + '_ { self.syntax.children() }

    /// Returns recovery nodes and tokens owned directly by this grammar node.
    #[must_use]
    pub fn errors(&self) -> impl Iterator<Item = AstError> + '_ {
        self.syntax.children_with_tokens().filter_map(AstError::cast)
    }

    #[must_use]
    pub fn inline_manifest(&self) -> Option<InlineManifest> {
        support::child(&self.syntax)
    }

    #[must_use]
    pub fn import_declarations(&self) -> AstChildren<ImportDeclaration> {
        support::children(&self.syntax)
    }

    #[must_use]
    pub fn declarations(&self) -> AstChildren<Declaration> {
        support::children(&self.syntax)
    }

    #[must_use]
    pub fn eof_token(&self) -> Option<SyntaxToken> {
        support::token(&self.syntax, SyntaxKind::Eof)
    }
}

